L000323	(-\omega)\right\rangle+2\left\langle\delta I_\mathrm{L/R}^{T_k}(\omega)\delta V_k
L000324	(-\omega)\right\rangle+\left\langle\delta V_k
L000325	(\omega)\delta V_k
